#include "gateway_config_page.h"

const char GATEWAY_CONFIG_PAGE[] =
"<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='color-scheme' content='dark'><title>AUBOT | Kết nối</title><link rel='stylesheet' href='/ui.css'><style>"
".config-card{min-width:0}.card-tools{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:-4px 0 13px}.static-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.ap-tools{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:12px;padding-top:12px;border-top:1px solid var(--line2)}.ap-actions{display:flex;gap:7px}.save-bar{display:flex;align-items:center;justify-content:flex-end;gap:13px;margin-top:14px;padding:13px 15px}.save-bar .message{flex:1;margin:0}.topic{overflow-wrap:anywhere}.mode-note{min-height:45px;display:flex;align-items:center;padding:9px 11px;border:1px solid var(--line2);border-radius:9px;background:var(--glass2);color:var(--muted);font-size:12px}@media(max-width:680px){.static-fields{grid-template-columns:1fr}.save-bar{align-items:stretch;flex-direction:column}.save-bar .btn{width:100%}.ap-tools{align-items:flex-start;flex-direction:column}}</style></head><body data-page='it'><div class='shell'>"
"<header class='hero'><div class='brand'><img class='logo' src='/logo.png' alt='AUBOT'><div><div class='eyebrow'>AUBOT · WAREHOUSE GATEWAY</div><h1>Cài đặt Gateway</h1><p>WiFi, Ethernet và MQTT</p></div></div><div class='header-status'><div data-app-user></div><div class='status-chip identity'><i></i><small>Gateway</small><b data-gw>--</b></div><div class='status-chip' data-network-chip><i></i><small>Mạng</small><b data-network>Đang đọc</b></div><div class='status-chip' data-mqtt-chip><i></i><small>MQTT</small><b data-mqtt>Đang đọc</b></div></div></header><nav class='nav' data-app-nav aria-label='Điều hướng chính'><a href='/'>TỔNG QUAN</a></nav>"
"<form id='form'><main class='layout'><section class='card config-card'><header class='card-head'><span class='step'>01</span><h2>Thiết bị</h2></header><div class='fields'><label class='field'><span>Mã Gateway</span><input id='gateway_id' maxlength='16' required></label><label class='field'><span>Mật khẩu WiFi AP</span><input id='ap_password' type='password' minlength='8' placeholder='Nhập nếu muốn đổi'></label></div><div class='ap-tools'><div><b>Điểm truy cập cấu hình</b><div id='stAp' class='hint'>Đang đọc trạng thái</div></div><div class='ap-actions'><button class='btn ghost' type='button' id='apOn'>Bật AP</button><button class='btn ghost' type='button' id='apOff'>Tắt AP</button></div></div></section>"
"<section class='card config-card'><header class='card-head'><span class='step'>02</span><h2>WiFi</h2></header><div class='fields'><label class='field full'><span>Tên WiFi</span><input id='wifi_ssid' list='nets' placeholder='Chọn hoặc nhập SSID'><datalist id='nets'></datalist></label><label class='field full'><span>Mật khẩu WiFi</span><input id='wifi_password' type='password'></label><label class='field full'><span>Cấp địa chỉ</span><select id='wifi_dhcp'><option value='1'>DHCP tự động</option><option value='0'>IP tĩnh</option></select></label></div><div id='wifiStatic' class='static-fields'><label class='field'><span>Địa chỉ IP</span><input id='wifi_ip'></label><label class='field'><span>Subnet mask</span><input id='wifi_netmask'></label><label class='field'><span>Gateway mạng</span><input id='wifi_gateway'></label><label class='field'><span>DNS</span><input id='wifi_dns'></label></div><div id='profiles' class='profiles'></div></section>"
"<section class='card config-card'><header class='card-head'><span class='step'>03</span><h2>Ethernet</h2></header><div class='field'><span class='field-label'>Chế độ hoạt động</span><div class='segmented'><button class='btn' type='button' id='ethDebug'>DEBUG</button><button class='btn' type='button' id='ethUplink'>UPLINK</button></div></div><div id='debugMode' class='mode-note' style='margin-top:11px'>IP cố định 169.254.1.1 /16 để kết nối trực tiếp với máy tính.</div><div id='uplinkMode' style='margin-top:11px'><label class='field'><span>Cấp địa chỉ</span><select id='eth_dhcp'><option value='1'>DHCP từ router</option><option value='0'>IP tĩnh</option></select></label><div id='ethStatic' class='static-fields' style='margin-top:11px'><label class='field'><span>Địa chỉ IP</span><input id='eth_ip'></label><label class='field'><span>Subnet mask</span><input id='eth_netmask'></label><label class='field'><span>Gateway mạng</span><input id='eth_gateway'></label><label class='field'><span>DNS</span><input id='eth_dns'></label></div></div></section>"
"<section class='card config-card'><header class='card-head'><span class='step'>04</span><h2>MQTT</h2><span class='badge'>JSON_WAREHOUSE_V1</span></header><div class='fields'><label class='field full'><span>Broker</span><input id='mqtt_broker' placeholder='mqtt.example.com hoặc 192.168.1.10'></label><label class='field'><span>Cổng</span><input id='mqtt_port' type='number' min='1' max='65535'></label><label class='field'><span>Giao thức</span><select id='mqtt_transport'><option value='tcp'>TCP</option><option value='tls'>TLS</option></select></label><label class='field'><span>Tên đăng nhập</span><input id='mqtt_user'></label><label class='field'><span>Mật khẩu</span><input id='mqtt_password' type='password' placeholder='Để trống nếu không đổi'></label><label class='field full'><span>Chu kỳ gửi (ms)</span><input id='publish_interval_ms' type='number' min='250' max='60000'></label></div><p class='hint topic'>Topic: <b id='topic'>gateway/--/status</b></p></section><section class='card config-card'><header class='card-head'><span class='step'>05</span><h2>Thời gian</h2><span id='timeState' class='badge'>Đang kiểm tra</span></header><div class='fields'><label class='field full'><span>SNTP chính</span><input id='sntp_primary' maxlength='63' required></label><label class='field full'><span>SNTP dự phòng</span><input id='sntp_fallback' maxlength='63'></label><label class='field full'><span>Múi giờ POSIX</span><input id='timezone' maxlength='63' required placeholder='ICT-7'></label></div><p class='hint'>Ví dụ Việt Nam: ICT-7. Thời gian hợp lệ là điều kiện để MQTT TLS hoạt động.</p></section></main><footer class='toolbar save-bar'><div id='feedback' class='message' role='status'>Chưa có thay đổi.</div><button class='btn primary' id='save' type='submit'>Lưu cấu hình</button></footer></form></div>"
"<script src='/ui.js'></script><script>const $=x=>document.getElementById(x),keys=['gateway_id','ap_password','wifi_dhcp','wifi_ip','wifi_netmask','wifi_gateway','wifi_dns','eth_dhcp','eth_ip','eth_netmask','eth_gateway','eth_dns','mqtt_broker','mqtt_port','mqtt_user','publish_interval_ms','sntp_primary','sntp_fallback','timezone'];const esc=x=>String(x).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));let ethUplink=false,statusTimer;function staticUi(){$('wifiStatic').classList.toggle('hidden',$('wifi_dhcp').value==='1');$('ethStatic').classList.toggle('hidden',$('eth_dhcp').value==='1')}function ethUi(){ $('ethDebug').classList.toggle('active',!ethUplink);$('ethUplink').classList.toggle('active',ethUplink);$('debugMode').classList.toggle('hidden',ethUplink);$('uplinkMode').classList.toggle('hidden',!ethUplink);staticUi()}function setEth(v){ethUplink=v;ethUi()}function hero(x){document.querySelector('[data-gw]').textContent=x.gateway_id;document.querySelector('[data-network]').textContent=x.network?x.network_name:'Chưa kết nối';document.querySelector('[data-mqtt]').textContent=x.mqtt?'Đã kết nối':'Chưa kết nối';document.querySelector('[data-network-chip]').classList.toggle('ok',x.network);document.querySelector('[data-mqtt-chip]').classList.toggle('ok',x.mqtt)}async function ap(enabled){const b=enabled?'Bật':'Tắt';if(!confirm(b+' điểm truy cập cấu hình?'))return;await fetch('/api/it/ap',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({enabled})});status()}async function load(){const r=await fetch('/api/it/config',{cache:'no-store'});if(r.status===401){location='/login';return}const c=await r.json();keys.forEach(k=>$(k).value=c[k]===undefined?'':c[k]);ethUplink=!!c.eth_router_mode;$('mqtt_transport').value=c.mqtt_transport;$('profiles').innerHTML=c.wifi_profiles.map(x=>`<span class='profile-chip'>${esc(x)}</span>`).join('')||'<span class=hint>Chưa lưu mạng WiFi</span>';$('topic').textContent=`gateway/${c.gateway_id}/status`;ethUi();scan();status()}async function scan(){try{const d=await(await fetch('/api/it/wifi-scan',{cache:'no-store'})).json();$('nets').innerHTML=d.networks.map(x=>`<option value='${esc(x.ssid)}'>${x.rssi} dBm</option>`).join('')}catch(e){}}async function status(){clearTimeout(statusTimer);try{const d=await(await fetch('/api/it/status',{cache:'no-store'})).json();$('stAp').textContent=d.ap?(d.ap_manual?'Đang phát · thủ công':'Đang phát · tự động'):'Đã tắt'}catch(e){}try{hero(await(await fetch('/api/ui/status',{cache:'no-store'})).json())}catch(e){}statusTimer=setTimeout(status,2000)}$('wifi_dhcp').onchange=$('eth_dhcp').onchange=staticUi;$('ethDebug').onclick=()=>setEth(false);$('ethUplink').onclick=()=>setEth(true);$('apOn').onclick=()=>ap(1);$('apOff').onclick=()=>ap(0);$('gateway_id').oninput=()=>$('topic').textContent=`gateway/${$('gateway_id').value||'--'}/status`;$('form').onsubmit=async e=>{e.preventDefault();const p=new URLSearchParams();keys.forEach(k=>p.set(k,$(k).value));p.set('eth_router_mode',ethUplink?'1':'0');p.set('mqtt_transport',$('mqtt_transport').value);['mqtt_password','wifi_ssid','wifi_password'].forEach(k=>p.set(k,$(k).value));const f=$('feedback'),save=$('save');save.disabled=true;f.textContent='Đang lưu cấu hình…';f.className='message';try{const r=await fetch('/api/it/config',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:p});if(!r.ok)throw Error(await r.text());f.textContent='Đã lưu. Gateway đang áp dụng cấu hình mới.';f.className='message ok';setTimeout(load,1000)}catch(x){f.textContent='Không thể lưu: '+x.message;f.className='message bad'}finally{save.disabled=false}};load()</script></body></html>";
